import * as T from 'three';
import {RanchRenderer} from './ranch-renderer.js';
import {OrbitControls} from './vendor/OrbitControls.js';
const $=id=>document.getElementById(id),canvas=$('units-canvas'),scene=new T.Scene();scene.background=new T.Color('#ececdb');scene.fog=new T.Fog('#ececdb',38,85);
const renderer=new RanchRenderer({canvas,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;
const camera=new T.PerspectiveCamera(35,1,.1,150),orbit=new OrbitControls(camera,canvas);orbit.enableDamping=true;orbit.maxPolarAngle=Math.PI*.47;orbit.minDistance=7;orbit.maxDistance=55;orbit.target.set(0,1,0);
scene.add(new T.HemisphereLight('#fff8e3','#7b8766',2.5));const sun=new T.DirectionalLight('#fff0d2',3.2);sun.position.set(-8,16,10);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-20,right:20,top:20,bottom:-20});sun.shadow.bias=-.0003;scene.add(sun);
const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.9,flatShading:true});const palette={wood:mat('#795b3e'),skin:mat('#c28e69'),iron:mat('#788784'),cream:mat('#e5d7b0'),boot:mat('#453c32'),hair:mat('#483b32'),gold:mat('#bb9551'),ground:mat('#b9c495'),edge:mat('#8a9874')};
function mesh(g,m,p,x=0,y=0,z=0){const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;p.add(o);return o;}
const box=(p,m,x,y,z,a,b,c)=>mesh(new T.BoxGeometry(a,b,c),m,p,x,y,z);
const ball=(p,m,x,y,z,a,b=a,c=a)=>{let o=mesh(new T.IcosahedronGeometry(1,1),m,p,x,y,z);o.scale.set(a,b,c);return o;};
const rod=(p,m,x,y,z,r,h)=>mesh(new T.CylinderGeometry(r,r,h,8),m,p,x,y,z);
const floor=mesh(new T.CylinderGeometry(70,70,.3,80),mat('#e1e3cd'),scene,0,-.6,0);floor.receiveShadow=true;
let group=new T.Group();scene.add(group);let actors=[];let cloth,accent,ink;const roles=['guard','pike','archer','scout','standard','rider'];const names={guard:'Shield guard',pike:'Pikeman',archer:'Archer',scout:'Scout',standard:'Standard bearer',rider:'Mounted captain'};const notes={guard:'Broad shield and close stance. Front-line protection.',pike:'Tall spear silhouette. Reach and formation identity.',archer:'Open bow profile and back quiver. Ranged support.',scout:'Hood, light equipment and compact blade. Reconnaissance.',standard:'Raised crest and flowing banner. Company identity.',rider:'Horse silhouette, saddle and plume. Mounted leadership.'};
function crest(p,x,y,z,s){if($('faction').value==='meadow'){const leaf=ball(p,accent,x,y,z,s*.16,s*.32,.025);leaf.rotation.z=-.4;}else if($('faction').value==='ochre'){ball(p,accent,x,y,z,s*.23,s*.23,.03);}else{for(let a of [-.65,.65])box(p,accent,x,y,z,s*.1,s*.65,.04).rotation.z=a;}}
function person(role,x,z,i){const root=new T.Group();root.position.set(x,0,z);group.add(root);const body=new T.Group();root.add(body);const legs=[],arms=[];let flag;
let base=0;if(role==='rider'){base=1.05;const horse=new T.Group();root.add(horse);ball(horse,palette.wood,0,1,0,.48,.53,.85);ball(horse,palette.wood,0,1.58,.55,.29,.59,.32);ball(horse,palette.wood,0,1.93,.83,.27,.28,.42);for(let side of [-1,1]){ball(horse,palette.wood,side*.17,2.23,.71,.07,.19,.08);for(let zz of [-.55,.55]){let leg=new T.Group();leg.position.set(side*.31,.8,zz);horse.add(leg);box(leg,palette.wood,0,-.36,0,.15,.72,.17);box(leg,palette.boot,0,-.73,.04,.18,.13,.25);legs.push(leg);}}box(horse,cloth,0,1.4,-.08,.85,.16,.72);box(horse,palette.boot,0,1.55,-.12,.5,.14,.45);ball(horse,palette.hair,0,1,-.87,.14,.46,.15);}
body.position.y=base;mesh(new T.CylinderGeometry(.26,.38,.63,8),cloth,body,0,1.05,0);box(body,palette.boot,0,.82,0,.61,.1,.4);box(body,accent,0,.83,.23,.12,.12,.04);
ball(body,palette.skin,0,1.64,.015,.265,.3,.25);ball(body,palette.hair,0,1.79,-.035,.27,.19,.25);box(body,palette.skin,0,1.64,.26,.09,.11,.07);for(let side of [-1,1]){ball(body,palette.boot,side*.105,1.7,.245,.022);const arm=new T.Group();arm.position.set(side*.36,1.3,0);body.add(arm);box(arm,cloth,0,-.15,0,.2,.34,.23);box(arm,palette.skin,0,-.4,0,.15,.24,.16);arms.push(arm);if(role!=='rider'){const leg=new T.Group();leg.position.set(side*.16,.78,0);body.add(leg);box(leg,palette.cream,0,-.22,0,.2,.44,.23);box(leg,palette.boot,0,-.57,.07,.22,.27,.34);legs.push(leg);}else box(body,palette.boot,side*.42,.55,.06,.18,.55,.26);}
if(role==='scout'||role==='archer'){ball(body,cloth,0,1.82,-.08,.31,.25,.28);box(body,cloth,0,1.19,-.25,.6,.65,.09);}else{mesh(new T.SphereGeometry(.29,8,4,0,Math.PI*2,0,Math.PI/2),ink,body,0,1.77,0);box(body,ink,0,1.78,.24,.58,.09,.1);}
if(role==='guard'){const shield=mesh(new T.CylinderGeometry(.42,.42,.1,10),cloth,arms[0],-.06,-.27,.24);shield.rotation.x=Math.PI/2;const rim=mesh(new T.TorusGeometry(.39,.035,5,12),palette.gold,arms[0],-.06,-.27,.3);crest(arms[0],-.06,-.27,.33,1);box(arms[1],ink,0,-.13,.1,.075,.9,.045);box(arms[1],palette.gold,0,-.43,.1,.28,.055,.08);}
if(role==='pike'||role==='standard'){rod(arms[1],palette.wood,0,.28,.08,.035,2.5);mesh(new T.ConeGeometry(.1,.3,4),ink,arms[1],0,1.67,.08);if(role==='standard'){flag=new T.Group();flag.position.set(.03,1.4,.08);arms[1].add(flag);box(flag,cloth,.38,-.35,0,.78,.65,.035);box(flag,accent,.38,-.65,.025,.78,.045,.04);crest(flag,.38,-.32,.04,.9);}}
if(role==='archer'){const pts=[];for(let j=0;j<=20;j++){const a=-Math.PI/2+j*Math.PI/20;pts.push(new T.Vector3(Math.cos(a)*.25,Math.sin(a)*.58,0));}const curve=new T.CatmullRomCurve3(pts);mesh(new T.TubeGeometry(curve,20,.025,5,false),palette.wood,arms[0],-.15,-.1,.2);box(arms[0],palette.cream,-.15,-.1,.2,.012,1.16,.012);rod(body,palette.boot,.21,1.14,-.28,.12,.65);for(let j=0;j<3;j++)rod(body,palette.wood,.14+j*.07,1.55,-.28,.013,.55);}
if(role==='scout'){box(arms[1],ink,0,-.32,.2,.075,.45,.04);ball(body,palette.wood,.34,.8,-.1,.15);}
if(role==='rider'){box(body,cloth,0,1.98,-.06,.09,.22,.35);rod(arms[1],palette.wood,0,.3,.05,.025,1.7);}
actors.push({root,body,legs,arms,flag,i,base});return root;}
function label(text,x,z){const c=document.createElement('canvas');c.width=512;c.height=80;const ctx=c.getContext('2d');ctx.fillStyle='#425740';ctx.font='500 34px system-ui';ctx.textAlign='center';ctx.fillText(text,256,48);const tex=new T.CanvasTexture(c),s=new T.Sprite(new T.SpriteMaterial({map:tex,depthTest:false}));s.position.set(x,.08,z);s.scale.set(3.8,.6,1);group.add(s);}
function rebuild(){group.traverse(o=>{o.geometry?.dispose();if(o.isSprite){o.material.map.dispose();o.material.dispose();}});scene.remove(group);group=new T.Group();scene.add(group);actors=[];cloth?.dispose();accent?.dispose();ink?.dispose();cloth=mat($('silhouette').checked?'#29352f':{meadow:'#55755b',ochre:'#b87b3d',bandit:'#82636b'}[$('faction').value]);accent=mat($('silhouette').checked?'#29352f':'#eadab0');ink=mat($('silhouette').checked?'#29352f':'#788784');
const roster=$('display').value==='roster',n=roster?6:Number($('count').value);for(let i=0;i<n;i++){let x,z;if(roster){x=(i%3-1)*4.5;z=(Math.floor(i/3)-.5)*5;}else{const f=$('formation').value;if(f==='ring'){x=Math.sin(i/n*Math.PI*2)*4;z=Math.cos(i/n*Math.PI*2)*4;}else if(f==='column'){x=(i%2-.5)*1.5;z=(Math.floor(i/2)-(n/2-1)/2)*1.6;}else if(f==='wedge'){x=(i%2?1:-1)*Math.ceil(i/2)*.63;z=Math.ceil(i/2)*.8-3;}else{x=(i%4-1.5)*1.6;z=(Math.floor(i/4)-(Math.ceil(n/4)-1)/2)*1.6;}}
const role=roster?roles[i]:$('role').value;person(role,x,z,i);if(roster){mesh(new T.CylinderGeometry(1.9,2,.25,6),palette.ground,group,x,-.18,z);label(names[role],x,z+1.65);}else if($('formation').value==='ring')actors.at(-1).root.rotation.y=i/n*Math.PI*2;}
if(!roster)mesh(new T.CylinderGeometry(11,11.2,.25,6),palette.ground,group,0,-.18,0);if($('silhouette').checked)group.traverse(o=>{if(o.isMesh&&o.parent!==group){o.material=cloth;o.userData.ranchInk=true;}});$('unit-description').textContent=notes[$('role').value];$('scene-caption').textContent=roster?'Six silhouettes. One little company.':n+' units · '+$('formation').selectedOptions[0].text+' · '+$('faction').selectedOptions[0].text;window.RanchView?.changed();}
function reset(){const d=Number($('distance').value);camera.position.set(d*.55,d*.62,d*.8);orbit.target.set(0,.7,0);orbit.update();}function resize(){const r=canvas.parentElement.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.fov=2*Math.atan(Math.tan(35*Math.PI/360)/Math.min(1,camera.aspect/1.25))*180/Math.PI;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(canvas.parentElement);
for(const id of ['display','role','faction','formation','count','silhouette'])$(id).addEventListener('change',()=>{if(['role','formation','count'].includes(id))$('display').value='company';rebuild();});$('distance').oninput=reset;$('reset-view').onclick=reset;
$('paused').checked=matchMedia('(prefers-reduced-motion: reduce)').matches;let t=0,last=performance.now();function render(){renderer.render(scene,camera);}function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;if(!$('paused').checked&&!document.hidden)t+=dt;const motion=$('motion').value;for(const a of actors){let phase=t*5+a.i*.7;const marching=motion==='march';a.body.position.y=a.base+(marching?Math.abs(Math.sin(phase))*.06:Math.sin(t*2+a.i)*.012);a.legs.forEach((l,j)=>l.rotation.x=marching?Math.sin(phase+j*Math.PI)*.38:0);a.arms.forEach((l,j)=>{l.rotation.x=marching?Math.sin(phase+j*Math.PI+Math.PI)*.28:0;l.rotation.z=motion==='rally'?(j?-.9:.9)+Math.sin(phase)*.1:0;});if(a.flag)a.flag.rotation.y=Math.sin(t*3+a.i)*.15;}orbit.update();render();requestAnimationFrame(frame);}reset();rebuild();resize();requestAnimationFrame(frame);
function spec(){return {version:1,study:'units',source:'original-procedural-study',role:$('role').value,faction:$('faction').value,display:$('display').value,formation:$('formation').value,count:actors.length,motion:$('motion').value,paused:$('paused').checked,silhouette:$('silhouette').checked,units:'metres',movementType:$('role').value==='rider'?'mounted':'foot',animations:['idle','march-in-place','rally'],anchors:['feet-origin','left-hand','right-hand','head'],limitations:['No combat or pathfinding','Procedural pivot animation; not a skeletal rig','Not an Asset Factory import']};}
$('export-unit').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(spec(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='ranch-unit-study.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};window.RanchView?.register('units',()=>({...spec(),camera:camera.position.toArray(),renderCalls:renderer.info.render.calls}),render);
